/* From Uiverse.io by nabilbdt  - Tags: simple, tooltip, action, alert, green, creative */
.__UIV_SCOPE__ .Tooltip {
  color: #ebebeb;
  border-radius: 0.8em;
  padding: 1em 4em;
  position: relative;
  display: inline-block;
  cursor: pointer;
  background-color: #00641e;
  -webkit-transition: background-color 2s ease-out;
  -moz-transition: background-color 2s ease-out;
  -o-transition: background-color 2s ease-out;
  transition: background-color 2s ease-out;
}
.__UIV_SCOPE__ .Tooltip .Tip {
  color: #003b12;
  text-align: center;
  border-radius: 5px;
  visibility: hidden;
  width: 100px;
  left: 100%;
  transform: translateX(-50%);
  opacity: 0;
  background-color: #28282817;
  padding: 10px;
  position: absolute;
  z-index: 1;
  bottom: 125%;
  transition: opacity 0.3s;
}
.__UIV_SCOPE__ .Tooltip:hover .Tip {
  opacity: 1;
  visibility: visible;
}
.__UIV_SCOPE__ .Tooltip:hover {
  background-color: rgb(100, 100, 100);
}
.__UIV_SCOPE__ .Tooltip .Tip::after {
  left: 10%;
  border-width: 8px;
  border-style: solid;
  content: "";
  position: absolute;
  top: 100%;
  border-color: #28282817 transparent transparent transparent;
}
